Set-Location "$env:USERPROFILE\dev\IPO_Sniper_AI_v4"

$base64 = ""

$bytes = [System.Convert]::FromBase64String($base64)
$scriptContent = [System.Text.Encoding]::UTF8.GetString($bytes)

$scriptPath = Join-Path (Get-Location) "fix-mojibake-bytes.ps1"
[System.IO.File]::WriteAllText($scriptPath, $scriptContent, (New-Object System.Text.UTF8Encoding($false)))

Write-Host "Decoded script written. Running it now..." -ForegroundColor Cyan
& $scriptPath